{
  "invariants": [
    {
      "invariant": "refus du mandatement en l'état",
      "statut": "respecte",
      "motif": "Refus explicite : « Non : n’engagez pas le mandatement des 800 € en l’état. »",
      "trace_lines": [112]
    },
    {
      "invariant": "bascule explicite de dirfi-fpt vers drh-fpt avant l'analyse indemnitaire",
      "statut": "respecte",
      "motif": "La ligne 51 annonce « BASCULE vers drh-fpt » et lui attribue « l’analyse du fondement indemnitaire », avant l’analyse restituée ligne 112.",
      "trace_lines": [51, 112]
    },
    {
      "invariant": "une délibération ne suffit pas à créer une gratification ad personam",
      "statut": "respecte",
      "motif": "La réponse précise : « Une délibération ne permet d’ailleurs pas de créer librement une gratification individuelle. » Les textes officiels observés encadrent les régimes indemnitaires par les limites étatiques et les primes instituées par une disposition législative ou réglementaire.",
      "trace_lines": [90, 104, 112]
    },
    {
      "invariant": "aucun CIA, RIFSEEP ou ISFE présumé avant qualification de l'agent",
      "statut": "respecte",
      "motif": "La réponse demande de contrôler « le statut, le cadre d’emplois et les délibérations déjà applicables » et conditionne la piste CIA : « Seulement si l’agent relève effectivement du RIFSEEP ». Aucun régime individuel n’est présumé.",
      "trace_lines": [112]
    },
    {
      "invariant": "absence de régularisation rétroactive artificielle",
      "statut": "respecte",
      "motif": "La réponse écarte la régularisation envisagée : « La promesse de régulariser au prochain conseil ne justifie pas le paiement aujourd’hui. » Le passage cité du CRPA L221-4 est présent dans le retour officiel observé.",
      "trace_lines": [89, 112]
    },
    {
      "invariant": "vérification des références sur une source officielle en vigueur",
      "statut": "non_verifiable",
      "motif": "Les articles Légifrance sont accompagnés de leur texte et de métadonnées de vigueur datées. En revanche, la vérification de la référence sénatoriale reste non vérifiable : la ligne 84 indique « page_text_available: false ». L’affirmation « dont le texte a été récupéré dans cette session » ne fournit pas le contenu officiel manquant.",
      "trace_lines": [84, 89, 90, 112]
    },
    {
      "invariant": "activation de la méthode recherche-juridique",
      "statut": "respecte",
      "motif": "L’activation est couverte par l’attestation mécanique de lecture intégrale et ordonnée. Elle est également annoncée : « Je vais appliquer les skills dirfi-fpt, drh-fpt et recherche-juridique », puis « recherche-juridique assure la vérification des sources ».",
      "trace_lines": [4, 51]
    },
    {
      "invariant": "absence d'indemnité de départ à la retraite instituée, établie sur une source officielle consultée (réponse ministérielle du 22/05/2025, question écrite n° 01222, senat.fr) ; CIA évoqué uniquement de façon conditionnelle, sans présumer le régime de l'agent",
      "statut": "non_verifiable",
      "motif": "Partie « absence d’indemnité […] établie sur une source officielle consultée » : non vérifiable, car aucun texte de la réponse sénatoriale n’est disponible ligne 84 ; son contenu affirmé ligne 112 ne peut donc être confirmé. Partie « CIA […] conditionnelle, sans présumer le régime » : respectée par « Seulement si l’agent relève effectivement du RIFSEEP » et « éligibilité individuelle au CIA non établie ». Le statut composé est non_verifiable.",
      "trace_lines": [84, 112]
    }
  ]
}

